    q:{en:"A 900 pF capacitor is charged by a 100 V battery. Using U = ½CV², the energy stored is closest to:", hi:"एक 900 pF capacitor 100 V की battery से charge किया जाता है। U = ½CV² इस्तेमाल करते हुए, जमा ऊर्जा सबसे क़रीब है:"},
    opts:{en:["4.5×10⁻⁶ J", "9×10⁻⁸ J", "4.5×10⁻⁴ J", "9×10⁻⁶ J"], hi:["4.5×10⁻⁶ J", "9×10⁻⁸ J", "4.5×10⁻⁴ J", "9×10⁻⁶ J"]},
    correct:"A", exp:{en:"U = ½×900×10⁻¹²×(100)² = ½×900×10⁻¹²×10⁴ = ½×9×10⁻⁶ = 4.5×10⁻⁶ J.", hi:"U = ½×900×10⁻¹²×(100)² = ½×900×10⁻¹²×10⁴ = ½×9×10⁻⁶ = 4.5×10⁻⁶ J."},
